(* [comment removed for export] *)
Lemma append_zero_long_x : forall (LB : list (Z * Z)) (cr : credit) (o q cap p sp r : Z) (s src : list Z),
  PML.cps_heap L HI PML.PC_STR_APPEND r sp PMS.STR_SCR LB cr
      (fun R M => (48 <= cap /\ len src = 0) /\ PML.entry L R M sp r PMS.STR_SCR /\ PML.a0 R o /\ PML.a1 R q /\ PML.a2 R (len src) /\
                  PML.str_at M o (PML.SLong cap p s) /\ In (p, cap) LB /\ PML.obj_on_stack L sp o 24)
