  PML.cps_heap L HI PML.PC_STR_APPEND r sp PMS.STR_SCR LB cr
      (fun R M => (48 <= cap /\ 1 <= len src /\ cap <= len s + len src <= 2 * cap - 2 /\ len s + len src < 2 ^ 47) /\ PML.entry L R M sp r PMS.STR_SCR /\ PML.a0 R o /\ PML.a1 R q /\ PML.a2 R (len src) /\
                  PML.str_at M o (PML.SLong cap p s) /\ In (p, cap) LB /\ PML.obj_on_stack L sp o 24 /\
                  L5.bytes_at GK.RSEGS M q src /\ PMES.src_ok L M LB sp o (PML.SLong cap p s) q (len src) /\ hl_k_per_malloc L <= fst cr)
